{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Olcegepant, a large peptidic CGRP antagonist with multiple amide and aromatic groups, has absolute oral bioavailability <1% in humans, showing that large polar peptidic scaffolds can be essentially non-absorbable orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dalfopristin, a macrocyclic peptidic antibiotic, has absolute oral bioavailability <5% in patients, directly demonstrating that macrocyclic peptide-like molecules with high size and polarity have very poor oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Almorexant, a complex heterocyclic drug with multiple aromatic rings and amide-like connectivity, has absolute oral bioavailability ~11% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "YH4808, a heterocyclic compound with moderate size, has absolute oral bioavailability 10.1% (range 2.3-19.3%), all below 20%, indicating low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Docetaxel, a large complex natural-product-like molecule, has absolute oral bioavailability ~8% due to poor permeability and first-pass/efflux liabilities, supporting low F for large complex scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "UK-427,857, a basic azacyclic drug, has human oral bioavailability 2.9 ± 1.7%, far below 20%, supporting low F for ionizable, high-MW compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well below 20% (mostly <13%, several <5%), and the query's large, polar, ionized macrocyclic scaffold is consistent with poor permeability and extensive first-pass/efflux liabilities. Therefore low F is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query.",
    "Retosiban, the highest-transfer analogue, has a borderline F range of 17-25% and was not used as affirmative low-F evidence.",
    "Exact transporter and first-pass metabolism profile of the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

